umber\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Subclass Number\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"3\"},{\"id\":\"5\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Location ID\"],\"expressionSourceColumns\":[\"Location ID\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Location ID\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Location ID\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"4\"}],\"recommendations\":[],\"dataSubsetInfos\":{\"queryEditMode\":1,\"filterbarSettings\":{},\"uiSqlStatement\":\"

-- ── Query 3 ────────────────────────────────────────────────────────────
SELECT STD_AV_IND FROM MFCS_RDS.RDS_WV_SYSTEM_OPTIONS\\n     WHERE ROWNUM = 1)                                    AS \\\"Cost Method Flag\\\",\\n    CASE (

-- ── Query 4 ────────────────────────────────────────────────────────────
SELECT STD_AV_IND FROM MFCS_RDS.RDS_WV_SYSTEM_OPTIONS\\n          WHERE ROWNUM = 1)\\n        WHEN 'A' THEN 'Weighted Average Cost'\\n        WHEN 'S' THEN 'Standard Cost'\\n    END                                                   AS \\\"Cost Method Description\\\"\\n\\nFROM\\n    MFCS_RDS.RDS_WV_WEEK_DATA               wd\\n\\n    LEFT JOIN MFCS_RDS.RDS_WV_PERIOD        p    ON  TRUNC(wd.EOW_DATE) = TRUNC(p.VDATE)\\n\\n    JOIN  MFCS_RDS.RDS_WV_DEPS              d    ON  wd.DEPT       = d.DEPT\\n    JOIN  MFCS_RDS.RDS_WV_CLASS             c    ON  wd.DEPT       = c.DEPT\\n                                                 AND wd.CLASS      = c.CLASS\\n    JOIN  MFCS_RDS.RDS_WV_SUBCLASS          sc   ON  wd.DEPT       = sc.DEPT\\n                                                 AND wd.CLASS      = sc.CLASS\\n                                                 AND wd.SUBCLASS   = sc.SUBCLASS\\n\\n    LEFT JOIN MFCS_RDS.RDS_WV_STORE         st   ON  wd.LOCATION   = st.STORE\\n                                                 AND wd.LOC_TYPE   = 'S'\\n    LEFT JOIN MFCS_RDS.RDS_WV_WH            wh   ON  wd.LOCATION   = wh.WH\\n                                                 AND wd.LOC_TYPE   = 'W'\\n\\nWHERE\\n    wd.EOW_DATE &gt;= ADD_MONTHS(SYSDATE, -3)\\n\\nORDER BY\\n    wd.HALF_NO,\\n    wd.MONTH_NO,\\n    wd.WEEK_NO,\\n    d.DEPT_NAME,\\n    c.CLASS_NAME,\\n    sc.SUB_NAME,\\n    CASE wd.LOC_TYPE WHEN 'S' THEN st.STORE_NAME WHEN 'W' THEN wh.WH_NAME END;\"},\"editorCurrentState\":false,\"joins\":{\"tables\":[]}}</ds:uiOptions><ds:version>v5</ds:version></ds:datasetImportOptions>","business-model":"\"\"","active":true,"custom-attrs":"{\"src_parquet_verified\":\"true\"}","description":"External dataset","display-name":"Manual Query","locale":"sys","is-user-striped":false,"file-length":0,"type":"sql","properties-last-modified":"2026-07-14T17:29:02.516+0000","connection-namespace":"disadmin_disadmin_APPID","private-connection":false,"credential-exists":true,"connection-name":"Remote RDS MFCS Connection","provider-type":"db","provider-name":"oracle","sso-enabled":false,"datamodelname":"'ReCommon'.'RPT_053_Weekly_Stock_Ledger_Detail'","parent-namespace":"ReCommon","parent-name":"RPT_053_Weekly_Stock_Ledger_Detail","data-access-mode":"auto","is-data-cacheable":true,"checkpoint-metadata-stale":false,"owner-guid":"ReCommon","is-temporary":false},"datasetType":"EMBEDDED","datamodelTwoPartName":"'ReCommon'.'RPT_053_Weekly_Stock_Ledger_Detail'"}
